<script lang="ts">
 import {onMount} from 'svelte';
 import type {Snippet} from 'svelte';
 import type {NavigationItem} from './types';
 import Icon from './Icon.svelte';
 import {useLocale,text} from '../locale';
 let {items,currentPath,label,compact=false,management=false,userName='',unreadCount=0,unreadBadge='',account,children}:{items:NavigationItem[];currentPath:string;label:string;compact?:boolean;management?:boolean;userName?:string;unreadCount?:number;unreadBadge?:string;account:Snippet;children:Snippet}=$props();
 const {locale}=useLocale();
 let menu:HTMLDialogElement;let ready=$state(false);
 const active=(href:string)=>currentPath===href||(href!=='/admin'&&currentPath.startsWith(href+'/'));
 const current=$derived(items.find(item=>active(item.href))?.label||label);
 $effect(()=>{currentPath;menu?.close();});
 onMount(()=>{ready=true;const media=matchMedia('(min-width:1000px)');const resize=()=>{if(media.matches)menu?.close();};media.addEventListener('change',resize);return()=>media.removeEventListener('change',resize);});
 function backdrop(event:MouseEvent){if(event.target!==menu)return;const b=menu.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)menu.close();}
</script>
{#snippet links()}
 <nav aria-label={label}>{#each items as item}<a href={item.href} aria-current={active(item.href)?'page':undefined} aria-label={item.label} title={item.label} onclick={()=>menu?.close()}><Icon name={item.icon} size={18}/><span>{item.label}</span></a>{/each}</nav>
{/snippet}
<div class="workspace-shell" class:compact class:management>
 <aside class="workspace-sidebar">
  <a class="workspace-brand" href="/" aria-label={text($locale,'Qmanga басты бет','Qmanga — главная')}><img src="/favicon.png" width="28" height="28" alt=""/><strong aria-hidden="true">manga<span class="brand-dot">.</span></strong></a>
  <div class="workspace-kind">{#if !management}<Icon name="users" size={18}/>{/if}<span>{management?text($locale,'Басқару панелі','Панель управления'):label}</span></div>
  {@render links()}
  <div class="sidebar-bottom"><a href="/help" aria-label={text($locale,'Көмек','Помощь')} title={text($locale,'Көмек','Помощь')}><Icon name="help" size={18}/><span>{text($locale,'Көмек','Помощь')}</span></a><a href="/" aria-label={text($locale,'Сайтқа оралу','Вернуться на сайт')} title={text($locale,'Сайтқа оралу','Вернуться на сайт')}><Icon name="left" size={18}/><span>{text($locale,'Сайтқа оралу','Вернуться на сайт')}</span></a>{#if management&&userName}<a class="workspace-profile" href="/settings"><span class="profile-initial" aria-hidden="true">{Array.from(userName)[0]}</span><span>{userName}<small>{text($locale,'Әкімші','Администратор')}</small></span></a>{/if}</div>
 </aside>
 <div class="workspace-body">
  <header class="workspace-topbar"><button class="workspace-menu" type="button" disabled={!ready} aria-label={text($locale,'Бөлімдерді ашу','Открыть разделы')} aria-haspopup="dialog" onclick={()=>menu.showModal()}><Icon name="menu"/></button><div class="workspace-crumbs"><a href={items[0]?.href}>{management?text($locale,'Әкімшілік','Администрирование'):label}</a><span aria-hidden="true">/</span><strong>{current}</strong></div><div class="workspace-account"><a class="workspace-catalog" href="/catalog" aria-label={text($locale,'Каталогтан іздеу','Поиск в каталоге')}><Icon name="search" size={18}/><span>{text($locale,'Іздеу','Поиск')}</span></a><a class="notifications-link" href="/notifications" aria-label={text($locale,'Хабарлар','Уведомления')+(unreadCount?' · '+unreadCount:'')}><Icon name="bell"/>{#if unreadBadge}<b class="unread-badge" aria-hidden="true">{unreadBadge}</b>{/if}</a>{@render account()}</div></header>
  <main id="content" class="workspace-main">{@render children()}</main>
 </div>
 <dialog bind:this={menu} class="workspace-drawer" aria-labelledby="workspace-menu-title" onclick={backdrop}><div class="drawer-heading"><h2 id="workspace-menu-title">{label}</h2><button type="button" aria-label={text($locale,'Жабу','Закрыть')} onclick={()=>menu.close()}><Icon name="close"/></button></div>{@render links()}<a class="drawer-return" href="/">← {text($locale,'Сайтқа оралу','Вернуться на сайт')}</a></dialog>
</div>
<style>
