;inset:0 auto 0 0;margin:0;width:min(300px,calc(100vw - 24px));height:100dvh;max-height:100dvh;padding:16px;border:0;border-right:1px solid var(--line);background:var(--panel);color:var(--text);overflow:auto}.workspace-drawer::backdrop{background:#0009}.drawer-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:16px}.drawer-heading h2{font-size:17px}.drawer-return{display:flex;align-items:center;min-height:44px;padding:8px 12px;margin-top:16px;color:var(--muted)}
