.notifications-link{position:relative}.unread-badge{position:absolute;top:0;right:0;border-radius:12px;padding:1px 4px;font-size:10px;background:var(--accent);color:var(--accent-ink)}.workspace-catalog{display:flex;align-items:center;gap:8px;min-height:44px;min-width:44px;justify-content:center;color:var(--muted);font-size:12px;border-radius:8px;background:var(--panel);padding:0 10px}.workspace-catalog span{display:none}@media(min-width:640px){.workspace-catalog{min-width:160px;justify-content:flex-start}.workspace-catalog span{display:inline}}.management{--panel:#231a17;--raised:#30231b;--line:#3d302b;--workspace-selected:#30231b}.management .workspace-sidebar{background:var(--bg)}.management .workspace-kind{background:none;padding:0;min-height:32px;color:var(--muted);text-transform:uppercase;font-size:11px}.management .workspace-brand{font-size:28px;letter-spacing:-1px}.management .workspace-brand img{width:36px;height:36px}.workspace-profile{display:flex;align-items:center;gap:10px;overflow-wrap:anywhere}.workspace-profile>span:last-child{min-width:0}.profile-initial{display:grid;place-items:center;border-radius:50%;width:38px;height:38px;flex:none;background:var(--raised);color:var(--accent)}.workspace-profile small{display:block;font-size:11px;color:var(--muted);margin-top:3px}@media(min-width:1000px){.workspace-shell.management{grid-template-columns:224px minmax(0,1fr)}.management .workspace-sidebar{padding:24px 20px 16px;gap:24px}.management nav a{padding-inline:12px}.management .workspace-main{padding:30px 32px 40px}.management .workspace-catalog{min-width:260px;background:none;border:1px solid var(--line)}}
